def get_shape(val: Any) ->Optional[List[int]]:
    """
    Get the shape of a tensor from a JIT value.

    Args:
        val: A torch._C.Value object from JIT IR

    Returns:
        A list of integers representing the shape, or None if the shape cannot be determined
    """
    try:
        val_type = val.type()
        if hasattr(val_type, 'sizes'):
            # For tensor types, get the sizes
            sizes = val_type.sizes()
            if sizes is not None:
                return list(sizes)
        elif hasattr(val_type, 'dim'):
            # Alternative way to get dimensions
            dim = val_type.dim()
            if dim is not None:
                return [val_type.size(i) for i in range(dim)]
    except (AttributeError, RuntimeError, TypeError):
        pass
    return None

def get_shape(val: Any) ->Optional[List[int]]:
    """
    Get the shape of a tensor from a JIT value.
    """
    try:
        val_type = val.type()
        # For TensorType, we can get sizes
        if hasattr(val_type, 'sizes'):
            sizes = val_type.sizes()
            return list(sizes) if sizes is not None else None
    except (AttributeError, RuntimeError, TypeError):
        pass
    return None
